-- small-art-doll-black-woman-with-basket (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'es', $tr$Pequeña muñeca artística: mujer negra con cesta$tr$, $tr$Pequeña muñeca de autor: una campesina negra con una cesta de verduras. Hecha en arcilla polimérica, pintada con acrílicos y vestida a mano. Figura única, hecha por completo a mano$tr$, $tr$Lleva una cesta llena de frutas y verduras recién recogidas, como si volviera a casa de un animado mercado de pueblo. Su sonrisa amable y su expresión serena transmiten calidez, bondad y la dignidad tranquila de la vida cotidiana. Vestida con un sencillo vestido de lino, collares y pulseras de cuentas de colores y un vivo pañuelo estampado en la cabeza, rinde homenaje a la belleza de la artesanía tradicional y del patrimonio cultural.

Hecha por completo a mano en arcilla polimérica sobre un armazón de alambre, cada detalle se ha modelado, pintado y montado a mano. El rostro expresivo, la ropa de textura trabajada con cuidado, los diminutos pies descalzos y la cesta rebosante de frutas y verduras en miniatura crean una escena llena de autenticidad y encanto. Los tonos naturales y ricos y los accesorios minuciosos dan vida al personaje y hacen que parezca recién llegada de un bullicioso mercado de pueblo.

Con unos 11 cm de altura, esta miniatura única es una pieza original de colección pensada para quienes aprecian el arte hecho a mano, los personajes expresivos y el folclore del mundo.$tr$, $tr$Pintura acrílica, arcilla polimérica, tela, lana$tr$, $tr$Modelado a mano, pintado a mano, hecho a mano$tr$
  FROM figurines WHERE slug = 'small-art-doll-black-woman-with-basket'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
