-- small-art-doll-falconer (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'es', $tr$Pequeña muñeca artística: cetrero$tr$, $tr$Pequeña muñeca artística: un hombre nativo americano. Hecha en arcilla polimérica, pintada con acrílicos y vestida a mano. El pájaro se puede quitar. Muñeca única, hecha por completo a mano. Unos 15 cm de altura$tr$, $tr$
Inspirada en las tradiciones de los pueblos nativos americanos, esta escultura en miniatura celebra la relación atemporal entre las personas y los animales salvajes. Cada detalle, desde el rostro expresivo y las manos modeladas con esmero hasta la ropa tejida y el tocado tradicional, se ha creado para transmitir la dignidad y la fuerza serena de un cetrero experto. El pájaro, que se puede quitar, añade un toque de realismo y permite contemplar la escena desde distintos ángulos.

Modelada por completo a mano en arcilla polimérica y pintada a mano, la figura viste ropa hecha a mano, con telas de textura marcada, adornos decorativos y colores terrosos que acompañan el vínculo del personaje con la naturaleza. Gracias a un armazón flexible de alambre, brazos y piernas se pueden colocar con suavidad, lo que da una vida sutil a esta miniatura única.

Con unos 15 cm de altura, esta muñeca artística única es más que una pieza de colección: es un pequeño homenaje a la sabiduría, a la tradición y al vínculo duradero entre las personas y las criaturas salvajes con las que comparten el mundo. Como toda obra hecha a mano, nunca habrá una segunda pieza exactamente igual, y eso hace de este cetrero una obra de arte en miniatura verdaderamente única.$tr$
  FROM figurines WHERE slug = 'small-art-doll-falconer'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-art-doll-forester (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'es', $tr$Pequeña muñeca artística: guardabosques$tr$, $tr$Pequeña muñeca de autor: un guardabosques con ardillas. Modelada en arcilla polimérica, pintada con acrílicos y vestida a mano. Figura única, hecha por completo a mano$tr$, $tr$Envuelto en una sencilla túnica de lino y una cálida capa de punto, este alegre caminante del bosque parece sentirse como en casa entre los animales. Dos diminutas ardillas lo han elegido como compañero de confianza: una posa orgullosa sobre su cabeza y la otra se asoma con ganas desde su mano, en un momento juguetón lleno de calidez y humor tranquilo.

Modelado por completo a mano en arcilla polimérica, cada detalle se ha hecho por separado y pintado con cuidado, desde su sonrisa expresiva y sus ojos bondadosos hasta las delicadas texturas de la barba y la ropa. Las ardillas en miniatura también están modeladas y pintadas a mano, cada una con su propio carácter, de modo que la composición parece una pequeña historia detenida en el tiempo.

Gracias a un armazón flexible de alambre, los brazos y las piernas de la muñeca se pueden recolocar con suavidad para variar ligeramente la postura. Con unos 9 cm de altura, esta miniatura única está pensada para coleccionistas que aprecian los personajes expresivos, el trabajo artesanal y los mundos de fantasía caprichosos.

Ya sea en una colección de temática del bosque, entre personajes de cuento o en un gabinete de curiosidades, este pequeño amigo del bosque transmite alegría, bondad y un asombro casi infantil. Cada elemento se ha modelado, pintado, vestido y montado por completo a mano, de modo que este personaje nunca podrá repetirse exactamente.$tr$, $tr$Pintura acrílica, arcilla polimérica, tela, lana$tr$, $tr$Modelado a mano, pintado a mano, hecho a mano$tr$
  FROM figurines WHERE slug = 'small-art-doll-forester'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
