       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-art-doll-gnome-with-gold (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'es', $tr$Pequeña muñeca artística: gnomo con oro$tr$, $tr$Pequeña muñeca de autor: un gnomo con oro. Modelada en arcilla polimérica, pintada con acrílicos y vestida a mano. Figura única, hecha por completo a mano$tr$, $tr$Este gnomo caprichoso parece recién salido de un viejo cuento del bosque: un poco gruñón, un poco misterioso y, a todas luces, nada impresionado por el mundo moderno. Su rostro expresivo, la larga barba alborotada, el sombrero marrón torcido y el traje amarillo vivo hecho a mano le dan un carácter maravillosamente excéntrico.

Lleva una diminuta cesta rústica llena de oro, como si acabara de volver de recoger algo importante en el bosque. Cada detalle está hecho a mano para crear la sensación de un personaje de cuento en miniatura, con su propia personalidad y su propia historia.

Una muñeca artística en miniatura única, hecha para coleccionistas que aman el folclore, la fantasía, los personajes hechos a mano y los mundos diminutos llenos de caracteres poco comunes.$tr$, $tr$Arcilla polimérica, pintura acrílica, barniz, alambre, tela, lana$tr$, $tr$Modelado a mano, pintado a mano, hecho a mano$tr$
