       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- small-art-doll-lady-agatha (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material)
SELECT id, 'es', $tr$Pequeña muñeca artística: Lady Agatha$tr$, $tr$Pequeña muñeca de autor: Lady Agatha. Hecha en arcilla polimérica, pintada con acrílicos y vestida a mano. Muñeca única hecha por completo a mano, por encargo$tr$, $tr$Modelada por completo a mano en arcilla polimérica, cada arruga, cada gesto amable y cada detalle delicado se ha formado y pintado uno por uno para darle una personalidad única. Su vestido hecho a mano se completa con un chal de encaje, un diminuto bolso de aire antiguo, un colgante en forma de corazón labrado y un elegante sombrero de plumas que añade un toque de encanto de otro tiempo. Gracias a un armazón flexible de alambre, sus brazos pueden recolocarse con suavidad para variar ligeramente la postura.

Con unos 10–11 cm de altura, es una pieza única de colección creada para quienes aprecian el arte en miniatura, los personajes expresivos y el trabajo artesanal. Ya sea en un gabinete de curiosidades, entre figuras de cuento o como parte de una colección personal, aporta calidez, elegancia y un sereno aire de misterio a cualquier lugar.

En su creación no se usan moldes ni técnicas de producción en serie. Cada etapa, desde el modelado y la pintura hasta la costura y el montaje, se ha hecho por completo a mano, así que esta pequeña dama es una obra de arte verdaderamente única que nunca podrá repetirse exactamente.$tr$, $tr$Pintura acrílica, arcilla polimérica, tela, lana$tr$
  FROM figurines WHERE slug = 'small-art-doll-lady-agatha'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material);

-- small-art-doll-lady-with-cat (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'es', $tr$Pequeña muñeca artística: dama con gato$tr$, $tr$Pequeña muñeca de autor: una dama con su gatito. Una brujita bondadosa hecha en arcilla polimérica, pintada con acrílicos y vestida a mano. Figura artística única, hecha por completo a mano.$tr$, $tr$Esta brujita no parece tanto una hechicera temible como una vieja bruja del bosque de carácter algo misterioso, casi tierno. El gato que lleva en brazos es lo que de verdad le da carácter.

Sostiene con cuidado en brazos un gatito atigrado, casi como si lo protegiera del frío. El contraste entre su aspecto algo extraño y curtido y la ternura con que sujeta al animalito la hace especialmente encantadora.

Tiene algo de misterio callado. Podría ser una bruja, una curandera, una anciana excéntrica que vive al borde del bosque o, quizá, las tres cosas a la vez. Su ropa parece tener historia propia: la tela de flores, el encaje oscuro, el sombrero de ala ancha y los zapatos negros puntiagudos dan la sensación de alguien que lleva muchísimo tiempo vagando por los cuentos.

Es una muñeca artística única, hecha por completo a mano, creada como un pequeño personaje y no como una simple figura decorativa. Parece alguien que tiene su casa en algún lugar más allá de la última aldea, donde empieza el bosque y las extrañas criaturitas saben exactamente a qué puerta llamar.
$tr$, $tr$Pintura acrílica, arcilla polimérica, tela, lana$tr$, $tr$Modelado a mano, pintado a mano, hecho a mano$tr$
  FROM figurines WHERE slug = 'small-art-doll-lady-with-cat'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- small-art-doll-little-ghost (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'es', $tr$Pequeña muñeca artística: fantasmita$tr$, $tr$Pequeña muñeca de autor: un fantasmita. Modelada en arcilla polimérica y pintada con acrílicos. Figura para colgar, hecha por completo a mano$tr$, $tr$Este fantasmita para colgar es un personaje diminuto, algo travieso, con una personalidad maravillosamente inquietante. Con sus enormes ojos azules, el pelo rojizo revuelto, la cara pálida y expresiva y su larga túnica blanca, parece un pequeño espíritu curioso que acaba de aparecer desde algún lugar entre el mundo real y una vieja casa encantada.

Está modelado por completo a mano en arcilla polimérica y pintado a mano con cuidado, y cada diminuto detalle se ha hecho a mano por separado. Su rostro expresivo, el peinado poco común, las manitas, los zapatos de aspecto gastado y la llave de aire antiguo que le cuelga del pecho le dan un carácter muy suyo y un aire de cuento algo misterioso.

Con unos 10–11 cm de altura, está pensado para colgarse como muñeca artística decorativa en miniatura. Los brazos son fijos y no se mueven, mientras que las piernas se pueden mover con suavidad para ajustar ligeramente su postura al colgar.

Es una miniatura única, hecha por completo a mano, así que nunca habrá otro exactamente igual. Está pensado para coleccionistas y para exponerse, no para jugar, y conviene manipularlo con cuidado por lo delicado de sus detalles.$tr$, $tr$Arcilla polimérica, pintura acrílica, barniz, alambre, tela, lana$tr$, $tr$Modelado a mano, pintado a mano, hecho a mano$tr$
  FROM figurines WHERE slug = 'small-art-doll-little-ghost'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
