-- small-art-doll-model (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'es', $tr$Pequeña muñeca artística: modelo$tr$, $tr$Pequeña muñeca de autor: una modelo (Janelle Monáe). Hecha en arcilla polimérica, pintada con acrílicos y vestida a mano. Obra única, hecha por completo a mano. Unos 15 cm de altura sin los sombreros$tr$, $tr$Inspirada en la imagen de Janelle Monáe, camina como si el mundo entero fuera su pasarela personal y mantiene en equilibrio, con una gracia natural, una extravagante torre de sombreros elegantes. Cada detalle de esta miniatura cuenta la historia de una mujer a la que su seguridad, su imaginación y su estilo inconfundible hacen inolvidable.

Modelada y montada por completo a mano, esta muñeca artística única combina la arcilla polimérica con tejidos confeccionados con cuidado, en una mezcla llamativa de escultura de moda y arte de personajes caprichosos.


Con unos 15 cm de altura, es una pieza de colección singular pensada para quienes aprecian las miniaturas expresivas hechas a mano, el arte imaginativo inspirado en la moda y las historias originales contadas en escultura.

Es más que una muñeca en miniatura: es una diminuta obra de arte que recoge la elegancia con un toque de humor e invita a inventar una historia nueva cada vez que se la mira.$tr$, $tr$Arcilla polimérica, pintura acrílica, barniz, alambre, tela, lana$tr$, $tr$Modelado a mano, pintado a mano, hecho a mano$tr$
  FROM figurines WHERE slug = 'small-art-doll-model'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
