       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-art-doll-piper (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material)
SELECT id, 'es', $tr$Pequeña muñeca artística: gaitero$tr$, $tr$Pequeña muñeca de autor: un gaitero con traje escocés, modelada en arcilla polimérica, pintada con acrílicos y vestida a mano.$tr$, $tr$Gaitero en miniatura hecho a mano

Este expresivo gaitero en miniatura recoge el espíritu de la música popular tradicional en un personaje encantador, hecho a mano y lleno de calidez y carácter. Aunque es pequeño, cada detalle habla de melodías de siempre, fiestas de pueblo y tradiciones centenarias.

El músico sostiene una gaita trabajada con cuidado, listo para llenar el aire con el sonido rico e inconfundible de este instrumento emblemático. Su expresión pensativa y su rostro amable y curtido sugieren años de experiencia, como si hubiera pasado la vida tocando en fiestas, bodas y reuniones por todo el campo.

Vestido con ropa de inspiración tradicional de las Tierras Altas, lleva una gorra estampada con una suave borla, un kilt clásico de tartán, medias de abrigo y un chaleco cálido ribeteado con piel sintética. Cada elemento del traje se ha pensado para acompañar al personaje y destacar el trabajo artesanal de la miniatura.

El rostro modelado, expresivo, con ojos cansados pero bondadosos y rasgos finamente detallados, da al gaitero una presencia muy viva y una personalidad única. Su postura algo encorvada y la manera cuidadosa en que sujeta el instrumento dan la impresión de que está a punto de empezar a tocar una vieja melodía querida.

Cada muñeca está modelada por completo a mano en arcilla polimérica y pintada a mano con minucia con acrílicos de alta calidad. La ropa y los accesorios se montan a mano uno por uno, y así cada figura es completamente única. No hay dos piezas exactamente iguales: cada gaitero tiene su propio carácter.

Ya sea en una colección de muñecas artísticas en miniatura, junto a una decoración de inspiración popular o como pieza singular que da que hablar, este gaitero hecho a mano aporta una sensación de tradición, nostalgia y relato tranquilo. Es una pieza de colección deliciosa para quienes aprecian el arte hecho a mano, la cultura celta, la música popular y las esculturas en miniatura muy detalladas.$tr$, $tr$Pintura acrílica, arcilla polimérica, tela, lana$tr$
  FROM figurines WHERE slug = 'small-art-doll-piper'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
