-- small-doll-baba-yaga (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'es', $tr$Pequeña Baba Yagá$tr$, $tr$Pequeña muñeca de autor: Baba Yagá con su escoba. Modelada en arcilla polimérica, pintada con acrílicos y vestida a mano. Figura única, hecha por completo a mano$tr$, $tr$
Modelada por completo a mano en arcilla polimérica y pintada a mano, esta figura en miniatura está llena de carácter y personalidad. Su rostro expresivo, los ojos brillantes y el pelo pelirrojo revuelto por el viento componen un retrato lleno de vida de la legendaria guardiana del bosque. Cada arruga, cada pliegue de la sonrisa y cada pequeño detalle se han trabajado a mano con cuidado, y le dan un espíritu único y muy suyo.

Viste ropa rústica en capas hecha a mano, inspirada en el folclore eslavo tradicional. En la mano lleva una escoba del bosque hecha a mano, símbolo emblemático de Baba Yagá y recordatorio de que la magia suele esconderse en los objetos más sencillos.

En lugar de presentarla solo como temible, esta escultura recoge el lado más misterioso y encantador de la legendaria bruja. Es la guardiana de un saber antiguo, la protectora de las viejas tradiciones y la guía imprevisible que pone a prueba el corazón de los viajeros antes de revelarles bendiciones ocultas.

Cada elemento de esta pieza de colección se ha hecho por completo a mano, desde el modelado y la pintura hasta la costura de la ropa y el montaje de cada diminuto accesorio. No se usan moldes ni reproducciones, así que cada figura es una verdadera obra de arte en miniatura única.$tr$
  FROM figurines WHERE slug = 'small-doll-baba-yaga'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
