-- small-doll-gnome-with-bag (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'es', $tr$Pequeño gnomo con mochila$tr$, $tr$Pequeña muñeca de autor: un gnomo con su mochila. Modelada en arcilla polimérica, pintada con acrílicos y vestida a mano. Figura única, hecha por completo a mano.$tr$, $tr$Te presentamos a este gnomo del bosque, pequeño y maravillosamente desaliñado, un caminante curioso que carga con una mochila enorme en su viaje por el bosque. Con su sombrero puntiagudo y torcido, el pelo rojo alborotado, su rostro expresivo, la ropa rústica y ese fardo descomunal, parece llevar años recorriendo senderos del bosque y haber conseguido reunir por el camino todo lo que pudiera llegar a necesitar.

Esta muñeca artística en miniatura, pieza única, está modelada y pintada a mano por completo, con un armazón de alambre en su interior que permite mover ligeramente brazos y piernas para cambiar la postura. Su ropa y sus accesorios están hechos a mano con tejidos diversos y materiales escogidos con cuidado, lo que le da un aspecto maravillosamente rústico y envejecido.

Con unos 10 cm de altura, quedaría muy bien en una colección de fantasía o de personajes del bosque, en una vitrina de miniaturas, en un diorama, en una escena de casa de muñecas o, sencillamente, en un lugar especial de una estantería desde donde un pequeño caminante del bosque pueda montar guardia.

Es una pieza única de colección hecha a mano: nunca habrá otra muñeca exactamente igual.$tr$, $tr$Arcilla polimérica, pintura acrílica, barniz, alambre, tela, lana$tr$, $tr$Modelado a mano, pintado a mano, hecho a mano$tr$
  FROM figurines WHERE slug = 'small-doll-gnome-with-bag'
