       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- small-doll-gnome-with-fancy-bag (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'es', $tr$Pequeño gnomo con mochila de colores$tr$, $tr$Pequeña muñeca con un hatillo de leña. Hecha en arcilla polimérica, pintada con acrílicos y vestida a mano. Figura única, hecha por completo a mano.$tr$, $tr$Te presentamos a este pequeño y curioso caminante del bosque, vestido con ropa rústica hecha a mano y cargado con una gran mochila de colores llena de tesoros misteriosos. Con su alto sombrero torcido, su rostro expresivo, el pelo algo revuelto y los largos zapatos puntiagudos, parece llevar ya bastante tiempo viajando por el bosque y, seguramente, tiene alguna que otra historia que contar.

Su enorme mochila está hecha con telas de textura marcada y decorada con detalles tejidos de colores, que contrastan de maravilla con su sencilla ropa oscura. Lleva un bastón de madera natural, que le da el aire de un viajero de los de antes, siempre listo para seguir su camino por otro sendero del bosque.

La muñeca está modelada y pintada a mano por completo, y cada detalle se ha hecho por separado. Un armazón de alambre en su interior permite mover ligeramente brazos y piernas para cambiar la postura. La ropa rústica, el alto sombrero hecho a mano, la mochila texturada, los botoncitos, los zapatos puntiagudos y el bastón de madera natural le dan su carácter único de viejo mundo.

Con unos 10-11 cm de altura, quedaría muy bien en una colección de fantasía o de personajes del bosque, en una vitrina de miniaturas, en un diorama, en una escena de casa de muñecas o, sencillamente, en un lugar especial de una estantería.

Es una muñeca artística verdaderamente única, hecha a mano: nunca habrá otra exactamente igual.$tr$, $tr$Arcilla polimérica, pintura acrílica, barniz, alambre, tela, lana$tr$, $tr$Modelado a mano, pintado a mano, hecho a mano$tr$
  FROM figurines WHERE slug = 'small-doll-gnome-with-fancy-bag'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
