       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material);

-- small-doll-witch (es)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material)
SELECT id, 'es', $tr$Pequeña muñeca: bruja$tr$, $tr$Pequeña muñeca de autor: una bruja con llaves, hecha en arcilla polimérica, pintada con acrílicos y vestida a mano. Unos 12-13 cm de altura$tr$, $tr$Bruja en miniatura con una llave antigua, hecha a mano

Misteriosa, astuta y llena de magia de otros tiempos, esta bruja en miniatura hecha a mano parece recién salida de un cuento olvidado. Su mirada penetrante y su sonrisa taimada insinúan innumerables secretos, y la gran llave antigua que lleva sugiere que solo ella sabe qué puertas ocultas puede abrir.

Su rostro expresivo está modelado con cuidado, con arrugas profundas, una larga nariz puntiaguda y una mueca traviesa inconfundible que da al personaje carácter y encanto. Enmarcada por una nube de pelo blanco, alborotado y esponjoso, tiene el aspecto atemporal de una antigua hechicera del bosque que lleva siglos vagando por las leyendas.

La bruja viste un amplio atuendo negro con un delicado ribete de encaje y una capa con capucha a juego que realza su silueta misteriosa. Del cuello le cuelgan diminutos talismanes y amuletos hechos a mano, reunidos en años de andanzas mágicas y rituales olvidados.

La llave envejecida, de color bronce, que le cuelga de la mano es más que un simple accesorio: invita a imaginar. ¿Abre un cofre encantado, la puerta oculta de un castillo o un paso entre mundos? Cada cual puede inventar su propia historia.

Modelada por completo a mano en arcilla polimérica y pintada a mano con cuidado con acrílicos de alta calidad, esta muñeca artística en miniatura está hecha con mucha atención a cada pequeño detalle. Cada pieza se hace una por una, y así cada bruja es un personaje verdaderamente único, con su propia expresión y su personalidad.

Ideal para coleccionistas de arte fantástico, folclore, decoración gótica y esculturas en miniatura, esta bruja caprichosa aporta una atmósfera encantada a cualquier vitrina. Ya sea en una estantería de libros, en un gabinete de curiosidades o entre la decoración de Halloween, seguro que se convierte en una pieza cautivadora que despierta la imaginación y las ganas de contar historias.$tr$, $tr$Pintura acrílica, arcilla polimérica, tela$tr$
  FROM figurines WHERE slug = 'small-doll-witch'
