       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- art-doll-captainsalazar (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'de', $tr$Künstlerpuppe: Kapitän Salazar$tr$, $tr$Kleine Künstlerpuppe: Kapitän Salazar. Aus Polymerton, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Künstlerpuppe, ein Unikat$tr$, $tr$Kapitän Salazar – handgefertigte Künstlerpuppe nach „Fluch der Karibik“

Ein Stück der verfluchten Karibischen See, zum Leben erweckt: Diese handgefertigte Künstlerpuppe in einem einzigen Exemplar zeigt Kapitän Armando Salazar, den legendären Piratenjäger aus „Pirates of the Caribbean: Salazars Rache“.

Einst ein gefürchteter Kapitän der spanischen Marine, widmete Salazar sein Leben der Jagd auf Piraten. Nachdem er im Teufelsdreieck gefangen war, kehrte er als Geisterkapitän zurück, der die untote Mannschaft der Silent Mary befehligt, getrieben von einem alten Groll gegen Jack Sparrow.

Mit etwa 20 cm (7,9 Zoll) Höhe fängt dieser Miniatur-Kapitän Salazar die dunkle, dramatische Stimmung der Figur ein. Sein strenger Ausdruck, das verwitterte Äußere, die an eine Marineuniform angelehnte Kleidung und seine unverkennbar geisterhafte Erscheinung geben ihm das Gefühl eines Kapitäns, der aus dem Meer zurückgekehrt ist, lange nachdem er hätte tot bleiben sollen.

Es hat etwas Passendes, Salazar als Miniatur zu haben: Nach Jahren im Teufelsdreieck hat er endlich einen Ort, an dem er stehen kann – auch wenn ich nicht erwarten würde, dass er dort lange still bleibt.$tr$, $tr$Acrylfarbe, Polymerton, Stoff, Wolle$tr$, $tr$Von Hand modelliert, von Hand bemalt, handgefertigt$tr$
  FROM figurines WHERE slug = 'art-doll-captainsalazar'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- granny-with-cats (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material)
SELECT id, 'de', $tr$Großmutter mit Katzen$tr$, $tr$Kleine Künstlerpuppe: Großmutter mit Katzen, aus Polymerton, von Hand bemalt und angekleidet$tr$, $tr$Großmutter mit Katzen – handgefertigte Künstlerpuppe, ein Unikat
(etwa 9–10 cm hoch / rund 3,5–4 Zoll)

Diese Miniatur-Künstlerpuppe einer Großmutter ist ein Unikat, vollständig von Hand aus Polymerton modelliert und sorgfältig mit hochwertigen Acrylfarben bemalt. Begleitet von ihren zwei geliebten getigerten Katzen, fängt sie einen herzerwärmenden Augenblick voller Zuneigung, Gemeinschaft und alltäglichem Charme ein.

Jedes Detail ist von Hand gefertigt, vom ausdrucksvollen Gesicht und dem sanften Lächeln bis zur handgenähten Kleidung und den winzigen Katzenfreunden. Eine Katze ruht bequem auf ihrer Schulter, die andere sitzt zu ihren Füßen – eine liebenswerte Szene, die ihre eigene Geschichte erzählt.

Dank eines Drahtgerüsts sind Arme und Beine beweglich; die Puppe trägt handgenähte Kleidung, die eigens für diese Gestalt entworfen wurde. Es werden keine Formen verwendet, und so ist sie ein echtes Unikat, das sich nicht genau wiederholen lässt.

Diese Miniatur-Künstlerpuppe passt zu Sammlern handgemachter Puppen, Katzenfreunden, Liebhabern der Volkskunst und allen, die eigenwillige Gestalten schätzen. Sie ist eine reizvolle Ergänzung für ein Regal, eine Kuriositätenvitrine oder eine Miniaturensammlung.

Die Puppe ist etwa 9–10 cm (3,5–4 Zoll) hoch; dazu gehören die beiden Miniaturkatzen auf den Fotos. Sie wird sorgfältig in schützender Verpackung verpackt und mit Sendungsnummer verschickt. Bitte behutsam behandeln: Sie ist ein zartes Sammlerstück, gedacht zum Betrachten und nicht zum Spielen.

Jede Puppe wird einzeln von Hand modelliert und erhält so ihr eigenes Wesen und ihren eigenen Charakter. Diese kleine Großmutter und ihre treuen Katzen bringen Wärme, Geborgenheit und den Zauber des Erzählens in jede Sammlung.$tr$, $tr$Polymerton, Acrylfarbe, Lack, Draht, Wolle, Stoff$tr$
  FROM figurines WHERE slug = 'granny-with-cats'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material);

