INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'de', $tr$Puppe: Jared Leto$tr$, $tr$Kleine Porträtpuppe von Jared Leto. Aus Polymerton modelliert, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat$tr$, $tr$Künstlerpuppe Jared Leto nach seinem Auftritt bei der Met Gala, handgefertigte Miniaturskulptur (9–10 cm), ein Unikat

Diese Miniatur-Künstlerpuppe in einem einzigen Exemplar ist etwa 9 bis 10 cm hoch und gibt Jared Letos berühmten Auftritt bei der Met Gala mit großer Liebe zum Detail wieder. Die Skulptur hat einen fein von Hand ausgearbeiteten Porträtkopf mit schulterlangem, dunklem, welligem Haar, sanften Gesichtszügen und einem gepflegten Bart und trifft die unverwechselbare Ähnlichkeit des Schauspielers.

Er trägt ein auffallendes, bodenlanges, leuchtend rotes Satinkleid mit hohem Ausschnitt und weit fallenden, drapierten Ärmeln. Über seine Schultern liegt ein kunstvolles Körpergeschirr aus schimmernden silbernen Strasssträngen, die anmutig über den roten Stoff herabfallen. In der linken Hand hält er eine Miniaturnachbildung seines eigenen modellierten Kopfes, mit passendem Haar und passenden Gesichtszügen, die den surrealen Augenblick auf dem Laufsteg nachstellen. Mit Sorgfalt von Hand gefertigt, ist dieses einzigartige Stück ein avantgardistischer Blickfang für Kunstsammler wie für Freunde der Popkultur.$tr$, $tr$Acrylfarbe, Polymerton, Stoff, Wolle$tr$, $tr$Von Hand modelliert, von Hand bemalt, handgefertigt$tr$
  FROM figurines WHERE slug = 'jared-leto-doll'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
