-- miniature-book-fairy-tales (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'de', $tr$Miniaturbuch: Märchen$tr$, $tr$Kleine Kunstfigur: Märchenbuch. Die Seiten sind aus Buchblättern gemacht. Der Gnom bewegt sich. Die Miniatur ist aus Polymerton und mit Acrylfarben bemalt. Ein vollständig handgefertigtes Kunstobjekt, ein Unikat$tr$, $tr$Jede große Geschichte beginnt mit den Worten „Es war einmal …“, und diese winzige Skulptur fängt den zauberhaften Augenblick kurz vor dem Abenteuer ein.

Verborgen zwischen den Seiten eines alten, abgegriffenen Märchenbuchs späht ein neugieriger kleiner Gnom still durch ein grobes Holzfenster.

Besonders zauberhaft macht diese Miniatur ihre sanfte Bewegung. Der Gnom hängt im Inneren des Buches und schwingt leise hin und her, als sei er lebendig. Bei jeder kleinen Bewegung scheint er sich aus seinem winzigen Fenster zu lehnen, um jeden zu begrüßen, der die Tür zu seinem Märchenhaus öffnet.

Das ganze Stück ist von Hand aus Polymerton und weiteren Materialien gefertigt, jede Oberfläche, jeder Pinselstrich und jede Verzierung sorgfältig von Hand gearbeitet. Der gealterte Buchdeckel, die winzigen Metallbeschläge, die bestoßenen Ecken und die handgeschriebene Inschrift lassen an einen uralten Zauberband denken, der zwischen seinen Seiten ein letztes Geheimnis bewahrt hat.

Diese Miniatur ist mehr als eine Skulptur – eine kleine Geschichte in drei Dimensionen, die dazu einlädt, sich die Abenteuer in jedem vergessenen Buch auszumalen. Als Sammlerstück in einem einzigen Exemplar gefertigt, feiert sie den zeitlosen Zauber der Märchen, die Neugier und den Glauben, dass sich zwischen den Seiten eines Buches noch immer außergewöhnliche Welten finden lassen.$tr$
  FROM figurines WHERE slug = 'miniature-book-fairy-tales'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- miniature-edgar-allan-poe-book-sculpture (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique, dimensions)
SELECT id, 'de', $tr$Miniatur-Buchskulptur: Edgar Allan Poe$tr$, $tr$Eine handgefertigte Miniatur-Buchskulptur in einem einzigen Exemplar nach Edgar Allan Poe, mit gotischem Turm, winziger Geisterfigur, bedruckten Papierseiten und einem Pendel. Etwa 11 cm hoch.$tr$, $tr$Eine Miniatur-Buchskulptur in einem einzigen Exemplar nach Edgar Allan Poe.
Etwa 11 cm hoch, mit dem Turm.

Diese kleine gotische Buchskulptur ist von Hand aus Polymerton gefertigt und sorgfältig mit Acrylfarben bemalt. Der Buchdeckel ist wie rissiges dunkles Holz mit Mauerwerk und Metallnieten gestaltet und trägt den handgeschriebenen Namen Edgar Allan Poe. Ein winziger Geist steht in der Tür, bedruckte Papierseiten bilden den Buchblock, und aus dem Inneren des Buches ragt ein kleines Pendel.

Einzelheiten

- Handgefertigte literarische Miniaturskulptur
- Nach Edgar Allan Poe und der Schauerliteratur
- Aus Polymerton modelliert und von Hand mit Acrylfarben bemalt
- Bedruckte Papierseiten
- Kleiner Turm und Mauerwerk obenauf
- Winzige Geisterfigur in der Tür
- Pendel im Inneren des Buches
- Innere Drahtstütze für mehr Halt
- Sammlerstück in einem einzigen Exemplar; Kopien werden nicht gemacht
- Höhe: etwa 11 cm

Passt gut zu

- Bücherfreunden und Sammlern von Schauerliteratur
- Vitrinen im Stil von Poe, Gotik oder Dark Academia
- Bücherregal-, Schreibtisch- oder Leseeckendekor
- Sammlungen von Miniaturen und Handarbeit
- einem besonderen handgemachten Geschenk für Liebhaber klassischer Gruselliteratur

Versand und Pflege

- Sorgfältig in schützender Verpackung verpackt
- Mit Sendungsnummer
- Bitte behutsam behandeln. Dies ist ein zerbrechliches handgemachtes Kunstobjekt, kein Spielzeug.

Jedes Stück wird einzeln von Hand modelliert und bemalt, und so hat das Miniaturbuch seine eigene gealterte Oberfläche, seine unheimliche Stimmung und seinen literarischen Charakter.$tr$, $tr$Polymerton, Acrylfarbe, Lack, Draht, Papier$tr$, $tr$Von Hand modelliert, von Hand bemalt, handgefertigt$tr$, $tr$Etwa 11 cm hoch$tr$
  FROM figurines WHERE slug = 'miniature-edgar-allan-poe-book-sculpture'
