SELECT id, 'de', $tr$Künstlerpuppe: Steampunk-Meerjungfrau$tr$, $tr$Eine bewegliche Künstlerpuppe in einem einzigen Exemplar: eine Meerjungfrau mit weichem Haar aus Wolle, einem Schwanz aus schwarzem Stoff und handgemachten Details im Steampunk-Stil. Etwa 15 cm hoch.$tr$, $tr$Eine handgefertigte Künstlerpuppe in einem einzigen Exemplar: eine Meerjungfrau im Steampunk-Stil.
