-- small-art-doll-esmeralda (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'de', $tr$Kleine Künstlerpuppe: Esmeralda$tr$, $tr$Kleine Künstlerpuppe: Esmeralda mit ihrer kleinen Ziege. Aus Polymerton, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat$tr$, $tr$Vollständig von Hand aus Polymerton modelliert und einzeln von Hand bemalt, ist diese Miniaturfigur einer der beliebtesten Heldinnen der Literatur gewidmet.

Esmeralda trägt eine an traditionelle Trachten angelehnte Kleidung: eine frische weiße Bluse, ein eng anliegendes schwarzes Mieder und einen leuchtend goldenen Rock, der bei jedem Schritt zu tanzen scheint. Ihr barfüßiger Stand zeigt ihre Nähe zur Erde und die Freiheit eines Lebens, das sich um keine Konventionen schert. Mit einer Hand rafft sie behutsam ihren Rock, in der anderen hält sie einen kleinen Schlüssel im alten Stil – ein sinnbildliches Detail, das unzählige Deutungen zulässt.

Neben ihr steht ihre treue kleine Ziege, eine unzertrennliche Gefährtin, die der Komposition Wärme und Erzählkraft gibt.

Jedes Element dieses Sammlerstücks ist einzeln von Hand gefertigt – vom Modellieren und Bemalen bis zum Nähen der Kleider und dem Zusammensetzen des kleinsten Zubehörs. Es werden weder Formen noch Kopien verwendet, und so bleibt diese Skulptur ein echtes Unikat der Miniaturkunst.$tr$
