-- small-art-doll-gnome-with-axe (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'de', $tr$Kleine Künstlerpuppe: Gnom mit Axt$tr$, $tr$Kleine Künstlerpuppe: kleiner Gnom mit Axt. Aus Polymerton, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Trollfigur, etwa 8 cm hoch$tr$, $tr$Vollständig von Hand aus Polymerton modelliert und einzeln von Hand bemalt, steckt diese Miniatur-Künstlerpuppe voller sorgfältig gearbeiteter Details. Sein ausdrucksvolles Gesicht ist von tiefen Falten und buschigen Augenbrauen gezeichnet und hat einen sanften, nachdenklichen Ausdruck, der ohne Worte Geschichten erzählt. Er trägt schlichte handgenähte Kleidung: eine strukturierte Weste, ein übergroßes Hemd wie aus Leinen, abgetragene Hosen, einen spitzen roten Hut und verwitterte Schuhe – genau passend für einen Wanderer, der sein Leben lang die Wildnis durchstreift hat.

Die detailreiche Miniatur-Streitaxt lässt sich aus seiner Hand nehmen; das macht die Skulptur noch lebendiger und betont, dass er eher ein alter Waldmann und Hüter des Waldes ist als ein Krieger. Dank eines biegsamen Drahtgerüsts lassen sich Arme und Beine behutsam bewegen, und kleine Änderungen der Haltung geben der Gestalt noch mehr Persönlichkeit.

Die etwa 8 cm (3,1 Zoll) hohe Miniatur ist ein Unikat und fängt den stillen Reiz klassischer Märchen und skandinavischer Volkssagen ein. Jede Skulptur entsteht vollständig von Hand – vom Modellieren und Bemalen bis zum Ankleiden und Zusammensetzen –, und so ist jedes Stück völlig einzigartig. Keine zwei Gnome gleichen einander genau, und dieser alte Waldhüter ist ein wirklich eigenständiges Werk der Miniaturkunst.$tr$
