-- small-art-doll-gnome-with-books (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'de', $tr$Kleine Künstlerpuppe: Gnom mit Büchern$tr$, $tr$Kleine Künstlerpuppe: kleiner Gnom mit Büchern. Aus Polymerton, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte bewegliche Figur, ein Unikat$tr$, $tr$Vollständig von Hand aus Polymerton modelliert und einzeln von Hand bemalt, wird diese Miniaturgestalt durch ausdrucksvoll modellierte Züge und sorgfältig gewählte Details lebendig. Das zerzauste kastanienbraune Haar, der lange Spitzhut, die übergroßen Schuhe und die winzigen handgemachten Bücher lassen ihn wirken wie einen Reisenden, der jahrelang auf der Suche nach vergessenem Wissen durch verwunschene Wälder gewandert ist.

Seine schlichte Kleidung ist vollständig von Hand aus Naturstoffen genäht, dazu ein gewebter Schal über den Schultern und ein Gürtel im alten Stil, der seine Waldkleidung abrundet. Jede Falte und jedes winzige Zubehörteil ist mit Bedacht gefertigt, um eine Gestalt voller Wärme und Persönlichkeit zu schaffen.

Obwohl nicht größer als eine Handfläche, hat der kleine Gelehrte eine unverkennbare Ausstrahlung. Mit einer zum Gruß ausgestreckten Hand und den Büchern dicht bei sich scheint er bereit, einen neuen Freund willkommen zu heißen oder eine außergewöhnliche Geschichte von seinem letzten Abenteuer zu erzählen.

Jedes Element dieses Sammlerstücks – vom Modellieren und Bemalen bis zum Nähen und Zusammensetzen – ist vollständig von Hand gefertigt, und so ist jede Figur völlig einzigartig. Es werden nie Formen oder Kopien verwendet, und so hat jeder Gnom sein ganz eigenes Wesen.$tr$
