-- small-art-doll-lady-with-cat (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'de', $tr$Kleine Künstlerpuppe: Dame mit Katze$tr$, $tr$Kleine Künstlerpuppe: Dame mit ihrem Kätzchen. Eine gütige kleine Hexe aus Polymerton, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat.$tr$, $tr$Diese kleine Hexe wirkt weniger wie eine furchterregende Zauberin als wie eine alte Waldhexe mit einem leicht geheimnisvollen, beinahe zärtlichen Wesen. Die Katze in ihren Armen gibt ihr erst ihren Charakter.

Sie hält eine kleine getigerte Katze behutsam im Arm, fast als wolle sie sie vor der Kälte schützen. Der Gegensatz zwischen ihrem etwas seltsamen, vom Wetter gezeichneten Äußeren und der sanften Art, wie sie das kleine Tier hält, macht sie besonders liebenswert.

Sie hat etwas still Geheimnisvolles. Sie könnte eine Hexe sein, eine Heilerin, eine verschrobene alte Frau am Waldrand – oder vielleicht alles zugleich. Ihre Kleidung scheint eine eigene Geschichte zu haben: Der geblümte Stoff, die dunkle Spitze, der breite Hut und die spitzen schwarzen Schuhe lassen an jemanden denken, der schon sehr lange durch Märchen wandert.

Sie ist eine vollständig handgefertigte Künstlerpuppe in einem einzigen Exemplar, als kleine Gestalt geschaffen und nicht bloß als Dekorationsfigur. Sie wirkt wie jemand, der irgendwo hinter dem letzten Dorf zu Hause ist, dort, wo der Wald beginnt und seltsame kleine Wesen genau wissen, an welche Tür sie klopfen müssen.$tr$, $tr$Acrylfarbe, Polymerton, Stoff, Wolle$tr$, $tr$Von Hand modelliert, von Hand bemalt, handgefertigt$tr$
