INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material)
SELECT id, 'de', $tr$Kleine Künstlerpuppe: Dudelsackspieler$tr$, $tr$Kleine Künstlerpuppe: Dudelsackspieler in schottischer Tracht, aus Polymerton modelliert, mit Acrylfarben bemalt und von Hand angekleidet.$tr$, $tr$Handgefertigter Miniatur-Dudelsackspieler

Dieser ausdrucksvolle Miniatur-Dudelsackspieler fängt den Geist traditioneller Volksmusik in einer reizvollen, handgemachten Gestalt voller Wärme und Persönlichkeit ein. Obwohl klein, erzählt jedes Detail von zeitlosen Melodien, Dorffesten und jahrhundertealten Traditionen.

Der Musikant hält einen sorgfältig gefertigten Dudelsack im Arm, bereit, die Luft mit dem vollen, unverwechselbaren Klang dieses berühmten Instruments zu erfüllen. Sein nachdenklicher Ausdruck und das sanfte, vom Wetter gezeichnete Gesicht lassen viele Jahre Erfahrung erahnen, als habe er sein Leben lang auf Festen, Hochzeiten und Zusammenkünften im ganzen Land gespielt.

Er trägt Kleidung nach dem Vorbild der Highlands: eine gemusterte Mütze mit weichem Bommel, einen klassischen Kilt im Tartanmuster, warme Strümpfe und eine gemütliche Weste mit Kunstpelzbesatz. Jedes Element der Tracht ist so gestaltet, dass es die Gestalt ergänzt und zugleich die Handarbeit der Miniatur zeigt.

Das ausdrucksvoll modellierte Gesicht mit den müden, aber gütigen Augen und den fein ausgearbeiteten Zügen gibt dem Dudelsackspieler eine lebensnahe Ausstrahlung und ein eigenes Wesen. Seine leicht gebeugte Haltung und der behutsame Griff um das Instrument erwecken den Eindruck, als wolle er gleich eine geliebte alte Weise anstimmen.

Jede Puppe ist vollständig von Hand aus Polymerton modelliert und sorgfältig von Hand mit hochwertigen Acrylfarben bemalt. Kleidung und Zubehör sind einzeln von Hand zusammengesetzt, und so ist jede Figur völlig einzigartig. Keine zwei Stücke gleichen einander genau, und jeder Dudelsackspieler hat seinen eigenen Charakter.

Ob in einer Sammlung von Miniatur-Künstlerpuppen, neben volkstümlichem Dekor oder als besonderes Gesprächsstück – dieser handgefertigte Dudelsackspieler bringt Tradition, Nostalgie und stilles Erzählen mit. Ein reizvolles Sammlerstück für Liebhaber von Handarbeit, keltischer Kultur, Volksmusik und fein ausgearbeiteter Miniaturskulpturen.$tr$, $tr$Acrylfarbe, Polymerton, Stoff, Wolle$tr$
  FROM figurines WHERE slug = 'small-art-doll-piper'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material);

-- small-art-doll-quazimodo (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'de', $tr$Kleine Künstlerpuppe: Quasimodo$tr$, $tr$Kleine Künstlerpuppe: Quasimodo. Aus Polymerton modelliert, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat$tr$, $tr$Vollständig von Hand aus Polymerton modelliert und einzeln von Hand bemalt, fängt diese Miniaturfigur die Menschlichkeit und das Gefühl von Victor Hugos unvergesslicher Gestalt ein.

Seine handgenähte Kleidung ist an mittelalterliche Bauerntracht angelehnt: abgetragene Stoffe, schlichte Oberflächen und erdige Farben, die von einem bescheidenen Leben zwischen den Steinmauern von Notre-Dame erzählen. Die übergroßen Schlüssel im alten Stil an seiner Seite stehen für seine Rolle als treuer Glöckner und Hüter der Kathedrale – ein Wächter, dem ihre verborgenen Gänge, verschlossenen Türen und Jahrhunderte voller Geschichte anvertraut sind.


Jedes Element dieses Sammlerstücks ist vollständig von Hand entstanden – vom Modellieren und Bemalen bis zum Nähen der Kleidung und dem Zusammensetzen jedes winzigen Zubehörteils. Es werden weder Formen noch Nachbildungen verwendet, und so bleibt jede Skulptur ein echtes Unikat der Miniaturkunst.

Ob unter literarischen Gestalten, mittelalterlichen Miniaturen oder feinen Künstlerpuppen – Quasimodo bringt ein starkes Gefühl für Geschichte, Empfindung und Erzählung in jede Sammlung. Mehr als das Bildnis einer berühmten Gestalt, ist er eine Hommage an Widerstandskraft und Treue und eine zeitlose Erinnerung daran, dass wahre Schönheit nicht im Äußeren liegt, sondern in Mitgefühl, Mut und der Stärke des menschlichen Geistes.$tr$
  FROM figurines WHERE slug = 'small-art-doll-quazimodo'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
