       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-art-doll-red-riding-hood (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'de', $tr$Kleine Künstlerpuppe: Rotkäppchen$tr$, $tr$Kleine Künstlerpuppe: Rotkäppchen mit Korb. Aus Polymerton modelliert, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat$tr$, $tr$Vollständig von Hand aus Polymerton modelliert und einzeln von Hand bemalt, fängt diese Miniaturfigur die Unschuld, die Neugier und den stillen Mut der klassischen Märchenheldin ein.

Sie trägt handgenähte Kleidung nach dem Vorbild traditioneller europäischer Volkstrachten: ein fließendes Kleid, eine Schürze und natürlich ihr berühmtes rotes Käppchen. Der winzige Korb vervollständigt die Szene und lädt dazu ein, ihn sich gefüllt vorzustellen – mit frischem Brot, Obst, Kräutern oder selbst gebackenen Leckereien für die geliebte Großmutter.


Jeder Teil dieses Sammlerstücks ist vollständig von Hand entstanden – vom Modellieren und Bemalen bis zum Nähen der Kleidung und dem Zusammensetzen des kleinsten Zubehörs. Es werden weder Formen noch Nachbildungen verwendet, und so ist jede Figur ein echtes Unikat der Miniaturkunst.

Ob unter Märchengestalten, Waldminiaturen oder feinen Künstlerpuppen – Rotkäppchen bringt Wärme, Nostalgie und zeitloses Erzählen in jede Sammlung. Sie würdigt das Staunen der Kindheit, den Mut und den bleibenden Zauber klassischer Volksmärchen und erinnert daran, dass selbst die kleinste Reisende sich auf die größten Abenteuer begeben kann.$tr$
