-- small-art-doll-shaman (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'de', $tr$Kleine Künstlerpuppe: Schamane$tr$, $tr$Kleine Künstlerpuppe: sibirischer Schamane aus Polymerton, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat.$tr$, $tr$Dieser alte sibirische Schamane sieht aus, als sei er gerade aus einer nordischen Sage getreten – von irgendwo jenseits der letzten Siedlung, wo sich der Wald endlos in den Schnee erstreckt.

Er trägt einen schweren braunen Mantel mit auffälligen rot-weißen traditionellen Mustern, lange rote Bahnen fallen an den Seiten herab, und um die Taille liegt ein breiter gewebter Gürtel. Sein wildes graues Haar und die pelzbesetzte Kopfbedeckung mit einem großen Geweih geben ihm unverkennbar die Ausstrahlung eines Menschen, der in die Wildnis gehört und nicht ins Dorf. In einer Hand hält er einen dunklen Stab, der nach Ritual aussieht, an seiner Seite hängt eine runde Handtrommel.

Geweih, Trommel, Pelz und die vielen Kleiderschichten erinnern an Bilder aus sibirischen Schamanentraditionen. In mehreren sibirischen Traditionen waren Rentiermotive und Geweihe eng mit der Schamanentracht und den Hilfsgeistern verbunden, und die Trommel war ein wichtiges Ritualinstrument.

Vollständig von Hand gefertigt und als Künstlerpuppe in einem einzigen Exemplar entstanden, verbindet er sagenhafte Kleidung, Miniaturzubehör, einen ausdrucksvollen Charakter und die Stimmung der fernen nördlichen Wildnis zu einem winzigen Erzähler, der aus einer anderen Welt gekommen zu sein scheint.$tr$, $tr$Acrylfarbe, Polymerton, Stoff, Wolle$tr$, $tr$Von Hand modelliert, von Hand bemalt, handgefertigt$tr$
