INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'de', $tr$Kleine Puppe: Gnom mit buntem Rucksack$tr$, $tr$Kleine Puppe mit einem Bündel Reisig. Aus Polymerton, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat.$tr$, $tr$Darf ich vorstellen: ein neugieriger kleiner Waldwanderer in schlichter handgenähter Kleidung, mit einem großen bunten Rucksack voller geheimnisvoller Schätze. Mit seinem hohen schiefen Hut, dem ausdrucksvollen Gesicht, dem leicht zerzausten Haar und den langen spitzen Schuhen sieht er aus, als wandere er schon eine ganze Weile durch den Wald – und habe wohl die eine oder andere Geschichte zu erzählen.

Der übergroße Rucksack ist aus strukturierten Stoffen genäht und mit bunten gewebten Mustern verziert, ein schöner Gegensatz zu seiner schlichten dunklen Kleidung. Er trägt einen naturbelassenen Wanderstock aus Holz und wirkt wie ein Reisender aus alter Zeit, der jederzeit bereit ist, den nächsten Waldpfad einzuschlagen.

Die Puppe ist vollständig von Hand modelliert und bemalt, jedes Detail einzeln gefertigt. Ein Drahtgerüst im Inneren erlaubt es, Arme und Beine leicht zu bewegen und die Haltung zu verändern. Die schlichte Kleidung, der hohe handgemachte Hut, der strukturierte Rucksack, die winzigen Knöpfe, die spitzen Schuhe und der Stab aus Naturholz geben ihm seinen ganz eigenen altweltlichen Charakter.

Mit etwa 10–11 cm Höhe ist er eine schöne Ergänzung für eine Fantasy- oder Waldsammlung, eine Miniaturvitrine, ein Diorama, eine Puppenhausszene oder einfach einen besonderen Platz im Regal.

Er ist eine echte handgefertigte Künstlerpuppe, ein Unikat – eine zweite genau wie ihn wird es nie geben.$tr$, $tr$Polymerton, Acrylfarbe, Lack, Draht, Stoff, Wolle$tr$, $tr$Von Hand modelliert, von Hand bemalt, handgefertigt$tr$
  FROM figurines WHERE slug = 'small-doll-gnome-with-fancy-bag'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
