-- small-doll-granny-with-chicken (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'de', $tr$Kleine Puppe: Großmutter mit Hühnern$tr$, $tr$Kleine Künstlerpuppe: Großmutter mit drei Hühnern. Aus Polymerton modelliert, mit Acrylfarben bemalt und von Hand angekleidet.$tr$, $tr$Kleine alte Frau füttert ihre Hennen

Handgefertigte Miniatur-Künstlerpuppe

Vom Alter gebeugt, aber voller stiller Entschlossenheit, trägt diese winzige Großmutter in jeder Falte ihres ausdrucksvollen Gesichts ein Leben voller Geschichten. Mit einer Handvoll Körner hält sie inne, um ihre drei neugierigen Hennen zu füttern – eines der einfachen Rituale, die unzählige stille Morgen auf dem Land erfüllt haben.

Vollständig von Hand aus Polymerton modelliert und sorgfältig von Hand bemalt, trägt die Puppe schlichte handgenähte Kleidung: eine abgetragene Schürze, ein weiches Kopftuch und traditionelle Dorfschuhe. Ihr vom Wetter gezeichneter Ausdruck, das sanfte Lächeln und die leicht gebeugte Haltung geben der Gestalt Wärme und Echtheit, und die drei Miniaturhennen runden die Szene mit Charme und Persönlichkeit ab.

Dank eines Drahtgerüsts lassen sich Arme und Beine behutsam bewegen und beim Aufstellen leicht anpassen. Jedes Detail – von den Falten der Kleidung über die Struktur der Haut bis zu den winzigen gemalten Federn der Hennen – ist vollständig von Hand gefertigt, und so ist jedes Stück wirklich einzigartig.

Diese Miniatur fängt die stille Schönheit des ländlichen Alltags ein und würdigt die Weisheit, Güte und Widerstandskraft von Generationen, die ihr Glück in einfachen Augenblicken fanden. Ob als Teil einer Dorfszene, einer Märchensammlung oder für sich allein – diese kleine Großmutter lädt dazu ein, sich die stille Welt vorzustellen, in der sie zu Hause ist.$tr$
