-- small-doll-granny-with-her-sheep (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'de', $tr$Kleine Puppe: Großmutter mit ihrem Schaf$tr$, $tr$Kleine Künstlerpuppe: Großmutter mit ihrem Schaf. Aus Polymerton modelliert, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat.$tr$, $tr$Diese reizende kleine Schäfergroßmutter sieht aus, als käme sie gerade aus einem stillen Dorf und führe ihr flauschiges Schaf behutsam einen alten Waldweg entlang. Ihr leicht verschmitztes Lächeln und das ausdrucksvolle Gesicht geben ihr ein warmes, verspieltes Wesen.

Sie trägt schlichte handgenähte Kleidung: einen strukturierten braunen Rock, eine cremefarbene Bluse, eine leuchtend gelbe Weste und ein dunkles Kopftuch. Ein winziger handgemachter Wanderstock rundet ihr Aussehen ab, und ihr flauschiges kleines Schaf folgt ihr dicht auf den Fersen.

Vollständig von Hand modelliert, bemalt, angekleidet und zusammengesetzt, ist sie eine Miniaturgestalt in einem einzigen Exemplar, mit großer Aufmerksamkeit für die winzigsten Details gefertigt. Zusammen erzählen die Großmutter und ihr Schaf eine schlichte kleine Geschichte vom Landleben, von Gemeinschaft und vom Wandern über Land.

Ein eigenwilliges Stück für Sammler handgemachter Miniaturkunst, volkstümlicher Gestalten und reizvoller Märchenszenen.$tr$
