-- small-doll-lady-with-pigeons (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'de', $tr$Kleine Puppe: Dame mit Tauben$tr$, $tr$Kleine Künstlerpuppe: Dame mit Tauben. Aus Polymerton, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat$tr$, $tr$Ihr Haar ist wild, ihr Lächeln schief, und in ihren Augen liegt jenes besondere Funkeln einer Frau, die weit mehr weiß, als sie zu sagen bereit ist. In einem verblichenen blauen Overall und leuchtend roten Schuhen geht sie, wohin ihre Tauben sie führen – und es sind nicht wenige.

Einige sitzen auf ihrem Hut und ihrer Schulter, andere folgen ihr treu zu Füßen. Sie trägt eine winzige rote Handtasche, vermutlich mit etwas Wichtigem darin … oder vielleicht nur mit Krümeln.

Sie hat etwas wunderbar Verschrobenes. Sie ist keine gewöhnliche Hexe und auch nicht ganz eine Waldgroßmutter. Eher eine Gestalt, die einfach aus einem alten Märchen herausspaziert ist und beschlossen hat zu bleiben.

Ein wenig geheimnisvoll, ein wenig verschmitzt, leicht vom Wetter gezeichnet und völlig unbekümmert darum, was andere von ihr denken.$tr$, $tr$Polymerton, Acrylfarbe, Lack, Draht, Stoff, Wolle$tr$, $tr$Von Hand modelliert, von Hand bemalt, handgefertigt$tr$
