-- small-doll-pirate-with-parrot (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'de', $tr$Kleine Puppe: Pirat mit Papagei$tr$, $tr$Kleine Künstlerpuppe: Pirat. Aus Polymerton, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat.$tr$, $tr$In dunklem Ledermantel und Mütze, mit abgetragenem Halstuch, Gürtel, Umhängetasche und einem winzigen Vogel auf der Schulter hat er unverkennbar die Ausstrahlung eines umherziehenden Halunken aus einem alten Geschichtenbuch.

Sein ausdrucksvolles Gesicht, der struppige Bart, die handgenähte Kleidung und der winzige Krummsäbel geben ihm viel Persönlichkeit, und der kleine Vogel fügt einen unerwarteten Hauch von Gemeinschaft hinzu. Er sieht aus, als wolle er gleich in einer mittelalterlichen Stadt, auf einem Waldpfad oder in der nächsten Schenke verschwinden – am liebsten, bevor jemand den Säbel bemerkt.

