       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- witch-with-scull (de)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'de', $tr$Hexe mit Totenkopf$tr$, $tr$Kleine Künstlerpuppe: Hexe mit Totenkopf. Aus Polymerton modelliert, mit Acrylfarben bemalt und von Hand angekleidet. Eine vollständig handgefertigte Figur, ein Unikat$tr$, $tr$Diese kleine Hexe sieht aus, als lebe sie schon seit einigen hundert Jahren am Rand eines sehr dunklen Waldes – und habe dabei so manches Geheimnis gesammelt.

Ihr wildes, wolkengleiches weißes Haar, das ausdrucksstarke Gesicht und ihr leicht verschmitztes Lächeln geben ihr unverkennbar einen altweltlichen Charakter. Sie trägt eine leuchtend gelbe Bluse unter einer schlichten braunen Weste, und Schichten abgetragenen, strukturierten Stoffs bilden ihren langen Rock. Überall an ihrer Kleidung finden sich winzige Details: ein Schlüssel im alten Stil, ein herzförmiger Anhänger, Ketten, kleine knochenartige Amulette und ein großer Totenkopf, der unten am Rock hängt.

Ihre Kleidung ist bewusst gealtert und leicht zerlumpt, und so wirkt sie weniger wie eine klassische Märchenhexe als wie eine seltsame kleine Wanderin, die jahrelang merkwürdige Dinge an vergessenen Orten gesammelt hat.

Die Puppe ist vollständig von Hand gefertigt: Gesicht, Hände, Kleidung, Haar und Miniaturzubehör sind einzeln von Hand gemacht und vollendet. Ein Drahtgerüst im Inneren erlaubt es, Arme und Beine behutsam zu bewegen und in Pose zu bringen.

Sie ist eine Künstlerpuppe in einem einzigen Exemplar, als kleine Gestalt geschaffen und nicht als Figur aus der Massenfertigung. Eine zweite genau wie sie wird es nie geben.$tr$, $tr$Acrylfarbe, Polymerton, Stoff, Wolle$tr$, $tr$Von Hand modelliert, von Hand bemalt, handgefertigt$tr$
  FROM figurines WHERE slug = 'witch-with-scull'
ON CONFLICT (figurine_id, lang) DO UPDATE
