-- art-doll-captainsalazar (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Bambola d’artista Capitano Salazar$tr$, $tr$Piccola bambola d’autore: il capitano Salazar. In argilla polimerica, dipinta con colori acrilici e vestita a mano. Bambola d’artista interamente fatta a mano, pezzo unico$tr$, $tr$Capitano Salazar – bambola d’artista fatta a mano, da «Pirati dei Caraibi»

Un frammento dei mari maledetti dei Caraibi in una bambola d’artista fatta a mano in un unico esemplare: il capitano Armando Salazar, il leggendario cacciatore di pirati di «Pirati dei Caraibi – La vendetta di Salazar».

Un tempo temibile capitano della Marina spagnola, Salazar dedicò la vita alla caccia ai pirati. Rimasto intrappolato nel Triangolo del Diavolo, tornò come capitano fantasma al comando dell’equipaggio di non morti della Silent Mary, spinto da un vecchio rancore verso Jack Sparrow.

Alto circa 20 cm, questo capitano Salazar in miniatura coglie l’atmosfera cupa e drammatica del personaggio. L’espressione severa, l’aspetto logorato, gli abiti di ispirazione navale e l’inconfondibile presenza spettrale lo fanno sembrare un capitano tornato dal mare molto tempo dopo il giorno in cui avrebbe dovuto restare morto.

C’è qualcosa di particolarmente giusto nell’avere Salazar in miniatura: dopo anni intrappolato nel Triangolo del Diavolo, finalmente ha un posto dove stare in piedi, anche se non mi aspetterei che ci rimanga tranquillo a lungo.$tr$, $tr$Colori acrilici, argilla polimerica, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
  FROM figurines WHERE slug = 'art-doll-captainsalazar'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- granny-with-cats (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material)
SELECT id, 'it', $tr$Nonna con i gatti$tr$, $tr$Piccola bambola d’autore: una nonna con i gatti, in argilla polimerica, dipinta e vestita a mano$tr$, $tr$Nonna con i gatti, pezzo unico – bambola d’artista fatta a mano
(alta circa 9–10 cm)

Questa bambola d’artista in miniatura, una nonna in un unico esemplare, è interamente modellata a mano in argilla polimerica e dipinta con cura con colori acrilici di alta qualità. Accompagnata dai suoi due amati gatti soriani, coglie un momento affettuoso fatto di tenerezza, di compagnia e del fascino delle cose di ogni giorno.

Ogni dettaglio è realizzato a mano, dal viso espressivo e dal sorriso gentile agli abiti cuciti a mano e ai minuscoli amici felini. Un gatto riposa comodo sulla sua spalla, l’altro siede ai suoi piedi, e la scena racconta una storia tutta sua.

Costruita su un’armatura di filo metallico, la bambola ha braccia e gambe mobili ed è vestita con abiti fatti a mano apposta per questo personaggio. Non si usano stampi: è un vero pezzo unico da collezione, che non si può riprodurre identico.

Questa bambola d’artista in miniatura è pensata per chi colleziona bambole fatte a mano, per chi ama i gatti e l’arte popolare, e per chi apprezza i personaggi bizzarri. Trova posto su uno scaffale, in una vetrina di curiosità o in una raccolta di miniature.

La bambola è alta circa 9–10 cm e comprende i due gatti in miniatura che si vedono nelle fotografie. Viene imballata con cura in una confezione protettiva e spedita con numero di tracciamento. Va maneggiata con cura: è un delicato oggetto d’arte da collezione, pensato per essere esposto e non per giocare.

Ogni bambola è modellata a mano una per una e ha un carattere tutto suo. Questa piccola nonna con i suoi fedeli compagni felini porta in una raccolta calore, conforto e un tocco di magia del racconto.$tr$, $tr$argilla polimerica, colori acrilici, vernice, filo metallico, lana, tessuto$tr$
  FROM figurines WHERE slug = 'granny-with-cats'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material);

-- granny-with-the-bird (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique, dimensions)
SELECT id, 'it', $tr$Nonna con l’uccellino$tr$, $tr$Una minuscola nonna fatta a mano con il suo uccellino. Bambola d’artista in un unico esemplare, modellata in argilla polimerica e dipinta a mano con colori acrilici. Alta circa 9–10 cm.$tr$, $tr$Questa bambola d’artista in miniatura, una nonna in un unico esemplare, è interamente modellata a mano in argilla polimerica e dipinta con cura con colori acrilici di alta qualità. Tiene tra le mani, con delicatezza, un minuscolo uccellino e coglie un momento quieto di gentilezza, di tenerezza e di legame con la natura.

Ogni dettaglio, dal viso espressivo e segnato dagli anni agli abiti cuciti a mano, è realizzato a mano per darle un carattere e una storia propri. L’espressione calda e la posa premurosa richiamano la vita tranquilla di paese, dove i momenti semplici diventano ricordi preziosi.

Costruita su un’armatura di filo metallico, la bambola ha braccia e gambe mobili ed è vestita con abiti fatti a mano apposta per questo personaggio. Non si usano stampi: è un vero pezzo unico da collezione, che non si può riprodurre identico.

Questa bambola d’artista in miniatura è pensata per chi colleziona bambole fatte a mano, arte popolare, interni rustici, vetrine di fiabe e miniature bizzarre. È anche un dono attento per chi ama gli uccelli e per chi apprezza le opere artigianali uniche.

La bambola è alta circa 9–10 cm. Viene imballata con cura in una confezione protettiva e spedita con numero di tracciamento. Va maneggiata con cura: è un delicato oggetto d’arte da collezione, pensato per essere esposto e non per giocare.

Ogni bambola è modellata a mano una per una, e ogni creazione ha il suo carattere, il suo fascino e la sua anima. Questa piccola nonna con il suo uccellino porta in una raccolta un tocco di calore, di dolcezza e di magia del racconto.$tr$, $tr$argilla polimerica, tessuto, colori acrilici, vernice, lana$tr$, $tr$modellatura$tr$, $tr$altezza 10 cm$tr$
