-- jared-leto-doll (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Bambola Jared Leto$tr$, $tr$Piccola bambola ritratto di Jared Leto. Modellata in argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura d’arte interamente fatta a mano, pezzo unico$tr$, $tr$Bambola d’artista Jared Leto al Met Gala, scultura in miniatura fatta a mano, pezzo unico (9–10 cm)

Questa bambola d’artista in miniatura, in un unico esemplare, è alta circa 9–10 cm e ricrea con grande attenzione al dettaglio la celebre apparizione di Jared Leto al Met Gala. La scultura ha una testa ritratto rifinita a mano con cura: capelli scuri e mossi fino alle spalle, lineamenti gentili e una barba curata, che colgono la somiglianza inconfondibile con l’attore.

Indossa un vistoso abito lungo fino a terra di raso rosso vivo, con il collo alto e ampie maniche drappeggiate. Sulle spalle porta un’elaborata imbracatura di fili di strass argentati e scintillanti, che scendono con grazia lungo tutto il tessuto rosso. Nella mano sinistra tiene una replica in miniatura della propria testa scolpita, con capelli e tratti del viso uguali, per ricreare il surreale momento sulla passerella. Realizzato a mano con cura, è un pezzo unico d’avanguardia per chi colleziona arte e per chi segue la cultura pop.$tr$, $tr$Colori acrilici, argilla polimerica, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
  FROM figurines WHERE slug = 'jared-leto-doll'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
