-- miniature-book-fairy-tales (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'it', $tr$Libro in miniatura Fiabe$tr$, $tr$Piccola figura d’arte: un libro di fiabe. Le pagine sono fatte con fogli di libro. Lo gnomo si muove. Miniatura in argilla polimerica dipinta con colori acrilici. Oggetto d’arte interamente fatto a mano, pezzo unico$tr$, $tr$Ogni grande storia comincia con le parole «C’era una volta...», e questa minuscola scultura coglie l’istante magico prima che l’avventura abbia inizio.

Nascosto tra le pagine di un vecchio libro di fiabe consunto, un piccolo gnomo curioso fa capolino in silenzio da una rustica finestrella di legno.

Ciò che rende questa miniatura particolarmente incantevole è il suo movimento lieve. Lo gnomo è sospeso all’interno del libro e oscilla piano avanti e indietro, dando l’illusione di essere vivo. A ogni piccolo movimento sembra sporgersi dalla sua finestrella, impaziente di salutare chiunque apra la porta della sua casa di fiaba.

L’intero pezzo è fatto a mano in argilla polimerica e tecnica mista, e ogni trama, ogni pennellata e ogni elemento decorativo è realizzato a mano con cura. La copertina invecchiata, i minuscoli dettagli in metallo, gli angoli consumati e la scritta a mano contribuiscono a dare l’impressione di un antico volume magico che ha custodito un ultimo segreto tra le sue pagine.

Questa miniatura è più di una scultura: è una piccola storia fermata in tre dimensioni, che invita a immaginare le avventure nascoste in ogni libro dimenticato. Pezzo unico da collezione, rende omaggio alla magia senza tempo delle fiabe, alla curiosità e alla convinzione che mondi straordinari si possano ancora trovare tra le pagine di un libro.$tr$
  FROM figurines WHERE slug = 'miniature-book-fairy-tales'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

