-- small-art-doll-black-woman-with-basket (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Piccola bambola d’artista Donna nera con il cesto$tr$, $tr$Piccola bambola d’autore: una contadina nera con un cesto di verdure. In argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura interamente fatta a mano, pezzo unico$tr$, $tr$Porta un cesto pieno di frutta e verdura appena raccolte, come se stesse tornando a casa da un vivace mercato di paese. Il sorriso gentile e l’espressione serena raccontano calore, bontà e la dignità quieta della vita di ogni giorno. Vestita con un semplice abito di lino, collane e braccialetti di perline colorate e un turbante dai disegni vivaci, rende omaggio alla bellezza dell’artigianato tradizionale e del patrimonio culturale.

Interamente fatta a mano in argilla polimerica su un’armatura di filo metallico, ogni dettaglio è stato modellato, dipinto e montato a mano. Il viso espressivo, gli abiti lavorati con cura nella trama, i minuscoli piedi scalzi e il cesto traboccante di frutta e verdura in miniatura creano una scena piena di autenticità e di fascino. I toni naturali e caldi e gli accessori minuziosi danno vita al personaggio, che sembra appena arrivata da un affollato mercato di villaggio.

Alta circa 11 cm, questa miniatura in un unico esemplare è un pezzo originale da collezione per chi ama l’arte fatta a mano, i personaggi espressivi e il folclore del mondo.$tr$, $tr$Colori acrilici, argilla polimerica, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
  FROM figurines WHERE slug = 'small-art-doll-black-woman-with-basket'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- small-art-doll-cooking-gnome (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Piccola bambola d’artista Gnomo cuoco$tr$, $tr$Piccola bambola d’autore: uno gnomo con la stufa e la pentola. In argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura interamente fatta a mano, pezzo unico$tr$, $tr$Un minuscolo gnomo sta accanto alla sua vecchia stufa di mattoni e mescola con cura, con un lungo mestolo, un calderone che borbotta. Se stia preparando una sostanziosa zuppa del bosco o una misteriosa pozione magica, è lasciato all’immaginazione.

La figura è interamente fatta a mano in argilla polimerica su un’armatura di filo metallico e vestita con abiti in miniatura cuciti con cura. Ogni dettaglio, dall’alto cappello a punta alle calze a righe, dalla stufa di mattoni consunta al minuscolo pentolino, è modellato, dipinto e montato a mano uno per uno. I colori caldi di terra e le trame ricche creano l’atmosfera raccolta di una casetta nascosta nel bosco, dove la magia e la vita di tutti i giorni stanno fianco a fianco.

Alta circa 10 cm, questa miniatura in un unico esemplare è un pezzo da collezione per chi ama il fantastico, il folclore e l’arte fatta a mano.$tr$, $tr$Colori acrilici, argilla polimerica, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
