-- small-art-doll-esmeralda (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'it', $tr$Piccola bambola d’artista Esmeralda$tr$, $tr$Piccola bambola d’autore: Esmeralda con la sua capretta. In argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura interamente fatta a mano, pezzo unico$tr$, $tr$
Interamente modellata a mano in argilla polimerica e dipinta a mano, questa figura in miniatura rende omaggio a una delle eroine più amate della letteratura.

Esmeralda indossa un abito d’ispirazione tradizionale: una camicetta bianca e fresca, un corpetto nero aderente e una gonna dorata e vivace che sembra pronta a danzare a ogni passo. I piedi scalzi raccontano la sua vicinanza alla terra e la libertà di una vita non costretta dalle convenzioni. Con una mano raccoglie piano la gonna, con l’altra tiene una piccola chiave di gusto antico, un dettaglio simbolico che si presta a infinite interpretazioni.

Accanto a lei c’è la sua fedele capretta, compagna inseparabile che aggiunge calore e racconto alla composizione.

Ogni elemento di questo pezzo da collezione è realizzato a mano, uno per uno: dalla modellatura e dalla pittura al cucito degli abiti e al montaggio dei più piccoli accessori. Non si usano stampi né copie, perciò questa scultura resta un’opera d’arte in miniatura davvero unica.
$tr$
  FROM figurines WHERE slug = 'small-art-doll-esmeralda'
