-- small-art-doll-falconer (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'it', $tr$Piccola bambola d’artista Falconiere$tr$, $tr$Piccola bambola d’artista: un nativo americano. In argilla polimerica, dipinta con colori acrilici e vestita a mano. L’uccello si può staccare. Bambola interamente fatta a mano, pezzo unico. Alta circa 15 cm$tr$, $tr$
Ispirata alle tradizioni dei nativi americani, questa scultura in miniatura celebra il legame antico tra l’uomo e gli animali selvatici. Ogni dettaglio, dal viso espressivo alle mani modellate con cura, dagli abiti intrecciati al copricapo tradizionale, è pensato per evocare la dignità e la forza quieta di un falconiere esperto. L’uccello, che si può staccare, aggiunge realismo e permette di guardare la scena da prospettive diverse.

Interamente modellata a mano in argilla polimerica e dipinta a mano, la figura indossa abiti cuciti a mano con tessuti materici, ornamenti decorativi e colori di terra che sottolineano il legame del personaggio con la natura. Grazie a un’armatura flessibile di filo metallico, braccia e gambe si possono mettere in posa con delicatezza, e la miniatura acquista una vita sottile.

Alta circa 15 cm, questa bambola d’artista in un unico esemplare è più di un pezzo da collezione: è un piccolo omaggio alla saggezza, alla tradizione e al legame duraturo tra le persone e le creature selvatiche che condividono il loro mondo. Come ogni opera fatta a mano, non ne esisterà mai una seconda identica, e questo falconiere resta un’opera d’arte in miniatura davvero unica.$tr$
  FROM figurines WHERE slug = 'small-art-doll-falconer'
