-- small-art-doll-forester (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Piccola bambola d’artista Guardaboschi$tr$, $tr$Piccola bambola d’autore: un guardaboschi con gli scoiattoli. Modellata in argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura interamente fatta a mano, pezzo unico$tr$, $tr$Avvolto in una semplice tunica di lino e in una calda mantellina lavorata a maglia, questo allegro piccolo viandante dei boschi sembra perfettamente a suo agio tra gli animali della foresta. Due minuscoli scoiattoli l’hanno scelto come compagno fidato: uno sta fiero sulla sua testa, mentre l’altro si sporge impaziente dalla sua mano, in un momento giocoso pieno di calore e di umorismo sommesso.

Interamente modellato a mano in argilla polimerica, ogni dettaglio è realizzato uno per uno e dipinto con cura, dal sorriso espressivo e dagli occhi buoni alle trame delicate della barba e degli abiti. Anche gli scoiattoli in miniatura sono modellati e dipinti a mano, ognuno con il suo carattere vivace, e la composizione sembra una minuscola storia fermata nel tempo.

Costruita su un’armatura flessibile di filo metallico, la bambola ha braccia e gambe che si possono spostare con delicatezza per variare leggermente la posa. Alta circa 9 cm, questa miniatura in un unico esemplare è pensata per chi apprezza i personaggi espressivi, il lavoro artigianale e i mondi fantastici e bizzarri.

In una raccolta dedicata al bosco, tra personaggi delle fiabe o in una raccolta di curiosità, questo piccolo amico della foresta porta allegria, gentilezza e uno stupore da bambini. Ogni elemento è stato modellato, dipinto, vestito e montato interamente a mano, perciò questo personaggio non potrà mai essere riprodotto identico.$tr$, $tr$Colori acrilici, argilla polimerica, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
  FROM figurines WHERE slug = 'small-art-doll-forester'
ON CONFLICT (figurine_id, lang) DO UPDATE
