       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-art-doll-gnome-2 (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Piccola bambola d’artista Gnomo$tr$, $tr$Piccola bambola d’autore: uno gnomo. In argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura d’arte interamente fatta a mano, pezzo unico$tr$, $tr$Gnomo dei boschi con il piccone, miniatura in un unico esemplare

Questo piccolo gnomo dispettoso sembra appena uscito da un bosco incantato, pronto a riprendere qualche misterioso lavoro. Con il naso storto, gli occhi infossati, i capelli grigi arruffati, la lunga barba e l’alto cappello a punta, ha il carattere inconfondibile di una vecchia creatura del bosco.

Interamente fatto a mano, modellato, dipinto, vestito e montato a mano pezzo per pezzo, porta un minuscolo piccone e indossa abiti rustici rossi e scuri con un mantello logoro da bosco. L’aria un po’ burbera gli dà un carattere deliziosamente stravagante.

Bambola d’artista in miniatura in un unico esemplare, trova posto in una raccolta fantasy, di folclore o di boschi incantati. Sembra un minuscolo abitante di un mondo molto più grande: un vecchio abitante del bosco con parecchi segreti e, probabilmente, un ottimo motivo per portarsi dietro quel piccone.$tr$, $tr$Argilla polimerica, colori acrilici, vernice, filo metallico, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
