-- small-art-doll-gnome-with-axe (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'it', $tr$Piccola bambola d’artista Gnomo con l’ascia$tr$, $tr$Piccola bambola d’autore: un piccolo gnomo con l’ascia. In argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura di troll interamente fatta a mano, alta circa 8 cm$tr$, $tr$

Interamente modellata a mano in argilla polimerica e dipinta a mano, questa bambola d’artista in miniatura è piena di dettagli curati. Il viso espressivo è segnato da rughe profonde, sopracciglia folte e un’espressione gentile e pensosa che racconta storie senza parole. Indossa abiti rustici cuciti a mano: un gilet materico, un’ampia camicia d’aspetto simile al lino, pantaloni consunti, un cappello rosso a punta e scarpe logore, adatti a un viandante che ha passato la vita a esplorare le terre selvagge.

L’ascia da battaglia in miniatura, ricca di dettagli, si può togliere dalla sua mano: aggiunge un elemento da maneggiare alla scultura e sottolinea il suo ruolo di vecchio boscaiolo e guardiano del bosco più che di guerriero. Costruita su un’armatura flessibile di filo metallico, la bambola ha braccia e gambe che si possono mettere in posa con delicatezza, per variare leggermente il portamento e dare ancora più carattere al personaggio.

Alta circa 8 cm, questa miniatura in un unico esemplare coglie il fascino quieto delle fiabe classiche e del folclore scandinavo. Ogni scultura è realizzata interamente a mano, dalla modellatura e dalla pittura alla vestizione e al montaggio, perciò ogni pezzo è del tutto unico. Non esistono due gnomi identici, e questo anziano guardiano del bosco è un’opera d’arte in miniatura davvero originale.$tr$
  FROM figurines WHERE slug = 'small-art-doll-gnome-with-axe'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
