-- small-art-doll-gnome-with-gold (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Piccola bambola d’artista Gnomo con l’oro$tr$, $tr$Piccola bambola d’autore: uno gnomo con l’oro. Modellata in argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura interamente fatta a mano, pezzo unico$tr$, $tr$Questo piccolo gnomo bizzarro sembra appena uscito da una vecchia storia del bosco: un po’ burbero, un po’ misterioso, e chiaramente poco colpito dal mondo moderno. Il viso espressivo, la lunga barba selvaggia, il cappello marrone storto e l’abito giallo vivo cucito a mano gli danno un carattere deliziosamente eccentrico.

Porta un minuscolo cestino rustico pieno d’oro, come se fosse appena tornato dal bosco dopo aver raccolto qualcosa di importante. Ogni dettaglio è fatto a mano per dare l’impressione di un personaggio da libro di fiabe in miniatura, con un carattere e una storia propri.

Bambola d’artista in miniatura in un unico esemplare, per chi ama il folclore, il fantastico, i personaggi fatti a mano e i mondi minuscoli pieni di tipi insoliti.$tr$, $tr$Argilla polimerica, colori acrilici, vernice, filo metallico, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
  FROM figurines WHERE slug = 'small-art-doll-gnome-with-gold'
