       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- small-art-doll-granny-with-hen (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Piccola bambola d’artista Nonna con la gallina$tr$, $tr$Piccola bambola d’autore: una nonna con le sue galline. Modellata in argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura interamente fatta a mano, pezzo unico$tr$, $tr$Nonna di campagna con le galline, miniatura in un unico esemplare

Questa dolce nonnina in miniatura sembra uscita da un tranquillo racconto di campagna. Con il sorriso gentile, il viso espressivo segnato dagli anni e tre galline curiose al fianco, racchiude il calore e la semplicità della vita rurale. Alla vita le pende una chiave di gusto antico, che lascia immaginare storie nascoste, ricordi cari o forse un piccolo segreto che aspetta di essere scoperto.

Alta circa 10 cm, questa bambola d’artista in un unico esemplare è interamente modellata a mano in argilla polimerica e dipinta con cura con colori acrilici di qualità artistica. Indossa abiti rustici cuciti a mano: una morbida camicetta di lino, una gonna verde, un caldo scialle lavorato a maglia

Ogni elemento è fatto a mano, dai tratti espressivi alle minuscole galline che la accompagnano, perciò nessun’altra bambola sarà mai identica. È pensata come pezzo d’arte in miniatura da collezione e non come giocattolo, e trova posto in una raccolta di arte popolare, in una vetrina di fiabe, in un interno rustico o in una raccolta di curiosità.

Realizzata con pazienza e con attenzione a ogni minimo dettaglio, questa piccola nonna rende omaggio alla bellezza quieta della vita di campagna e al fascino del lavoro artigianale. È un pezzo unico per chi ama i personaggi bizzarri, le storie e l’arte in miniatura.$tr$, $tr$Argilla polimerica, colori acrilici, vernice, filo metallico, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
  FROM figurines WHERE slug = 'small-art-doll-granny-with-hen'
