-- small-art-doll-little-ghost (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Piccola bambola d’artista Fantasmino$tr$, $tr$Piccola bambola d’autore: un fantasmino. Modellata in argilla polimerica e dipinta con colori acrilici. Statuina da appendere interamente fatta a mano$tr$, $tr$Questo fantasmino da appendere è un personaggio minuscolo, un po’ dispettoso, con un carattere deliziosamente spettrale. Con i grandi occhi azzurri, i capelli rossicci spettinati, il viso pallido ed espressivo e la lunga veste bianca, sembra un piccolo spirito curioso appena comparso da qualche parte tra il mondo reale e una vecchia casa infestata.

È interamente modellato a mano in argilla polimerica e dipinto a mano con cura, e ogni minuscolo dettaglio è realizzato a mano uno per uno. Il viso espressivo, l’acconciatura insolita, le manine, le scarpe dall’aria consunta e la chiave di gusto antico che gli pende sul petto gli danno un carattere tutto suo e un’atmosfera un po’ misteriosa da libro di fiabe.

Alto circa 10–11 cm, è pensato per essere appeso come bambola d’artista decorativa in miniatura. Le braccia sono fisse e non si muovono, mentre le gambe si muovono con delicatezza e permettono di aggiustare un po’ la posa sospesa.

È una miniatura in un unico esemplare, realizzata interamente a mano: non ce ne sarà mai un’altra identica. È pensata per chi colleziona e per essere esposta, non per giocare, e va maneggiata con delicatezza per via dei suoi dettagli fragili.$tr$, $tr$Argilla polimerica, colori acrilici, vernice, filo metallico, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
  FROM figurines WHERE slug = 'small-art-doll-little-ghost'
