-- small-art-doll-model (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Piccola bambola d’artista Modella$tr$, $tr$Piccola bambola d’autore: una modella (Janelle Monáe). In argilla polimerica, dipinta con colori acrilici e vestita a mano. Opera interamente fatta a mano, pezzo unico. Alta circa 15 cm senza i cappelli$tr$, $tr$Ispirata all’immagine di Janelle Monáe, cammina come se il mondo intero fosse la sua passerella personale, tenendo in equilibrio con grazia naturale una torre stravagante di cappelli eleganti. Ogni dettaglio di questa miniatura racconta la storia di una donna che la sicurezza, l’immaginazione e un senso dello stile inconfondibile rendono indimenticabile.

Interamente modellata e montata a mano, questa bambola d’artista in un unico esemplare unisce l’argilla polimerica a tessuti cuciti con cura, in un incontro sorprendente tra scultura di moda e personaggio bizzarro.


Alta circa 15 cm, è un pezzo unico da collezione per chi apprezza le miniature espressive fatte a mano, l’arte fantasiosa ispirata alla moda e il racconto scultoreo originale.

È più di una bambola in miniatura: è una minuscola opera d’arte che coglie l’eleganza con un tocco di umorismo, e invita chi la guarda a inventare ogni volta una storia nuova.$tr$, $tr$Argilla polimerica, colori acrilici, vernice, filo metallico, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
  FROM figurines WHERE slug = 'small-art-doll-model'
