-- small-art-doll-quazimodo (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'it', $tr$Piccola bambola d’artista Quasimodo$tr$, $tr$Piccola bambola d’autore: Quasimodo. Modellata in argilla polimerica, dipinta con colori acrilici e vestita a mano. Statuina interamente fatta a mano, pezzo unico$tr$, $tr$

Interamente modellata a mano in argilla polimerica e dipinta a mano, questa figura in miniatura coglie l’umanità e l’emozione dell’indimenticabile personaggio di Victor Hugo.

Gli abiti cuciti a mano sono ispirati a quelli dei contadini medievali: tessuti consunti, trame semplici e colori di terra che raccontano una vita umile trascorsa tra le mura di pietra di Notre-Dame. Le grandi chiavi di gusto antico che gli pendono al fianco sono il simbolo del suo ruolo di campanaro e custode devoto della cattedrale, guardiano dei suoi passaggi nascosti, delle sue porte chiuse e di secoli di storia.


Ogni elemento di questo pezzo da collezione è realizzato interamente a mano: dalla modellatura e dalla pittura al cucito degli abiti e al montaggio di ogni minuscolo accessorio. Non si usano stampi né riproduzioni, perciò ogni scultura resta un’autentica opera d’arte in miniatura in un unico esemplare.

Tra personaggi letterari, miniature medievali o bambole d’artista, Quasimodo porta in una raccolta un forte senso di storia, di emozione e di racconto. Più che il ritratto di un personaggio famoso, è un omaggio alla capacità di resistere, alla lealtà e al ricordo senza tempo che la vera bellezza non sta nell’aspetto esteriore, ma nella compassione, nel coraggio e nella forza dello spirito umano.$tr$
  FROM figurines WHERE slug = 'small-art-doll-quazimodo'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-art-doll-red-riding-hood (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'it', $tr$Piccola bambola d’artista Cappuccetto Rosso$tr$, $tr$Piccola bambola d’autore: Cappuccetto Rosso con il cestino. Modellata in argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura interamente fatta a mano, pezzo unico$tr$, $tr$Interamente modellata a mano in argilla polimerica e dipinta a mano, questa figura in miniatura coglie l’innocenza, la curiosità e il coraggio quieto della classica eroina delle fiabe.

Indossa abiti cuciti a mano ispirati ai costumi popolari tradizionali europei: un vestito fluente, il grembiule e, naturalmente, il suo celebre cappuccio rosso. Il minuscolo cestino completa la scena e invita a immaginarlo pieno di pane fresco, frutta, erbe o dolci fatti in casa per l’amata nonna.


Ogni aspetto di questo pezzo da collezione è realizzato interamente a mano: dalla modellatura e dalla pittura al cucito degli abiti e al montaggio dei più piccoli accessori. Non si usano stampi né riproduzioni, perciò ogni figura è un’autentica opera d’arte in miniatura in un unico esemplare.

Tra personaggi delle fiabe, miniature del bosco o bambole d’artista, Cappuccetto Rosso porta in una raccolta calore, nostalgia e il racconto senza tempo. Rende omaggio allo stupore dell’infanzia, al coraggio e alla magia duratura del folclore classico, e ricorda che anche il più piccolo viandante può partire per le avventure più grandi.$tr$
  FROM figurines WHERE slug = 'small-art-doll-red-riding-hood'
ON CONFLICT (figurine_id, lang) DO UPDATE
