       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-art-doll-shaman (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Piccola bambola d’artista Sciamano$tr$, $tr$Piccola bambola d’autore: uno sciamano siberiano in argilla polimerica, dipinto con colori acrilici e vestito a mano. Figura d’arte interamente fatta a mano, pezzo unico.$tr$, $tr$Questo vecchio sciamano siberiano sembra appena uscito da una leggenda del Nord, da qualche parte oltre l’ultimo villaggio, dove la foresta si stende senza fine nella neve.

Indossa un pesante cappotto marrone decorato con vistosi motivi tradizionali rossi e bianchi, con lunghe falde rosse che scendono dai fianchi e un’ampia cintura intrecciata in vita. I capelli grigi arruffati e il copricapo di pelliccia, sormontato da grandi corna, gli danno la presenza inconfondibile di chi appartiene alle terre selvagge più che al villaggio. In una mano tiene un bastone scuro dall’aria rituale, mentre al fianco gli pende un tamburo rotondo.

Le corna, il tamburo, la pelliccia e gli abiti a strati richiamano le immagini delle tradizioni sciamaniche siberiane. In diverse tradizioni della Siberia la renna e le sue corna erano strettamente legate all’abito dello sciamano e agli spiriti aiutanti, mentre il tamburo era un importante strumento rituale.

Interamente fatto a mano come bambola d’artista in un unico esemplare, unisce abiti ispirati al folclore, accessori in miniatura, un carattere espressivo e l’atmosfera delle lontane terre selvagge del Nord in un minuscolo narratore che sembra arrivato da un altro mondo.
$tr$, $tr$Colori acrilici, argilla polimerica, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
  FROM figurines WHERE slug = 'small-art-doll-shaman'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- small-art-doll-shaman-woman (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, technique)
SELECT id, 'it', $tr$Piccola bambola d’artista Sciamana$tr$, $tr$Piccola bambola d’autore: una sciamana in argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura snodabile, pezzo unico.$tr$, $tr$
Modellata a mano in argilla polimerica e dipinta a mano, questa figura in miniatura è ricca di trame e di carattere. Strati di tessuti invecchiati le ricadono addosso con naturalezza, mentre collane e braccialetti fatti a mano e dettagli scelti con cura danno l’impressione di un abito cerimoniale raccolto nel corso di molti anni.

Pur nelle piccole dimensioni, ha una presenza notevole. Senza affidarsi a gesti teatrali, la scultura trasmette una forza quieta e un sapere interiore profondo. Non è ritratta come una maga temibile, ma come una saggia custode di riti dimenticati: guaritrice, narratrice e guardiana delle tradizioni degli antenati.

Ogni aspetto della figura, dal viso espressivo agli abiti a strati ai dettagli dipinti con cura, è realizzato interamente a mano, e questo la rende un pezzo del tutto unico. Non si usano stampi né copie: resta davvero un esemplare unico da collezione.


