       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-doll-baba-yaga-2 (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'it', $tr$Piccola bambola Baba Yaga con la scopa$tr$, $tr$Piccola bambola d’autore: Baba Yaga con la scopa. In argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura interamente fatta a mano, pezzo unico.$tr$, $tr$Bambola d’artista Baba Yaga con la scopa fatta a mano, pezzo unico (alta circa 14–15 cm)

Nel mondo incantato del folclore slavo, con questa bambola d’artista in miniatura in un unico esemplare: Baba Yaga. Saggia, misteriosa e indimenticabile, compare come la leggendaria strega che abita nel folto dei boschi antichi. Stringendo la sua scopa rustica fatta a mano, sembra pronta a sparire lungo sentieri nascosti o a partire per un altro viaggio magico nelle terre selvagge.

Interamente modellata a mano in argilla polimerica e dipinta a mano con minuzia con colori acrilici di alta qualità, è fatta a mano in ogni dettaglio. Il viso profondamente espressivo, gli occhi penetranti, la pelle segnata dal tempo e i capelli ribelli danno vita a questo celebre personaggio del folclore. Indossa abiti cuciti a mano a più strati, con uno scialle consunto, un grembiule rustico e indumenti ispirati a quelli tradizionali di paese, che rispecchiano l’aspetto senza tempo della leggendaria strega.

Ogni bambola è modellata, dipinta e montata a mano una per una, perciò non esistono due pezzi uguali. Con il viso segnato, l’espressione di chi sa e la scopa tradizionale, questa Baba Yaga in miniatura coglie il mistero, la saggezza e lo spirito duraturo di una delle figure più affascinanti del folclore dell’Europa orientale. Che la si immagini come una maga temibile, una guardiana del bosco o una custode di segreti antichi, è un pezzo da collezione davvero unico, che porta la magia delle vecchie leggende in una raccolta.$tr$
  FROM figurines WHERE slug = 'small-doll-baba-yaga-2'
