-- small-doll-witch-in-black (it)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'it', $tr$Piccola bambola Strega in nero$tr$, $tr$Piccola bambola d’autore: una strega vestita di nero. In argilla polimerica, dipinta con colori acrilici e vestita a mano. Figura d’arte interamente fatta a mano, pezzo unico$tr$, $tr$Bambola d’artista Strega del bosco con scopa e chiave, scultura in miniatura fatta a mano, pezzo unico (9–10 cm)

Questa bambola d’artista in miniatura, una strega in un unico esemplare, è alta circa 9–10 cm e ha un aspetto sinistro ma avvincente, pieno del carattere delle fiabe più cupe. Il viso, modellato a mano con minuzia, ha un’espressione feroce e minacciosa: occhi intensi sotto la fronte aggrottata, un naso adunco e storto dalla superficie molto lavorata e una bocca beffarda che lascia vedere denti aguzzi, uno per uno. Una nuvola di capelli grigi selvaggi le scende sulle spalle da sotto un alto cappello nero a punta, piegato in modo teatrale.

Indossa una lunga veste nera con le maniche lunghe, dagli orli sfilacciati, che le dà un aspetto antico e mistico. Al collo, ben in vista come un medaglione, pende una grande chiave d’ottone lavorata, di gusto antico. Nella mano stringe un alto ramo di legno con alla base una scopa di paglia naturale, e tiene la sua posa delicata in equilibrio su sottili stivaletti neri a punta. Ogni dettaglio è fatto a mano, e questa miniatura da collezione è un pezzo davvero unico per chi ama l’arte fantastica e il folclore più oscuro.$tr$, $tr$Colori acrilici, argilla polimerica, tessuto, lana$tr$, $tr$Modellatura a mano, pittura a mano, lavorazione artigianale$tr$
  FROM figurines WHERE slug = 'small-doll-witch-in-black'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
